INSERT INTO reviews (sku, rating, title, body, author_name, is_verified, is_approved, created_at) VALUES
  ('AUD-01M325429', 5, 'Correct fit, sealed properly', 'Second one of these I have bought, this time for the RS4 B7. Dimensions matched the outgoing filter to the millimetre. It dropped straight into the housing and the cap torqued to spec first go. Result is no leaks at all after several hundred miles.', 'Thomas Nair', true, TRUE, '2026-04-20T06:37:57.179Z'),
  ('AUD-01M325429', 5, 'Good pleat count', 'Bought for a 2007 Q5 8R. Dimensions matched the outgoing filter to the millimetre. The old one practically fell apart coming out; this went in cleanly. Result is throttle response feels crisper than it did on the clogged original. Will be back for the other side.', 'Rajesh Almeida', true, TRUE, '2026-05-04T05:56:53.030Z'),
  ('AUD-01M325429', 5, 'Genuine quality for less', 'Went on my A7 4G 2.0 TFSI at 168k miles. The rubber seal is supple and sat in its groove without coaxing. I pre-oiled the seal before fitting and there has not been a drop since. Result is oil pressure comes up as quickly on a cold start as it always has. No complaints at all.', 'Chidi Moreau', true, TRUE, '2025-07-25T15:33:03.504Z'),
  ('AUD-021115562A', 4, 'Correct fit, sealed properly', 'Cross-referenced the OE number against my 2016 Q8 4M before ordering. The old one practically fell apart coming out; this went in cleanly. Dimensions matched the outgoing filter to the millimetre. Result is throttle response feels crisper than it did on the clogged original.', 'Camille Moreau', true, TRUE, '2026-04-26T14:23:17.122Z'),
  ('AUD-022905715D', 5, 'Straight fix for a rough idle', 'Second one of these I have bought, this time for the A6 C8. The part number on the body matches the OE reference exactly. A smear of dielectric grease went on the boot before it was seated. Result is it pulls cleanly through the rev range again with no stumble under load.', 'Talia Larsen', true, TRUE, '2025-05-28T08:43:04.672Z'),
  ('AUD-022905715E', 4, 'Engine light off first drive', 'Cross-referenced the OE number against my 2020 A4 B8.5 before ordering. Coil pack out, new one in, ten minutes with a T30 and the engine cover off. The boot is proper thick silicone, not the thin rubber the cheap ones use. Result is cold starts are smooth instead of shaking the whole car. Will be back for the other side.', 'Viktor Novotny', true, TRUE, '2025-10-13T06:01:46.526Z'),
  ('AUD-022905715E', 5, 'Cured my P0303', 'Bought for a 2009 S4 B8. I replaced all four at once rather than chase them one at a time. The part number on the body matches the OE reference exactly. Result is it pulls cleanly through the rev range again with no stumble under load. Exactly what I needed.', 'Yusuf Bergmann', false, TRUE, '2025-04-01T21:41:14.976Z'),
  ('AUD-032905106F', 4, 'Misfire cleared instantly', 'Went on my A3 8V 1.8 TFSI at 123k miles. I swapped it on the roadside when the car dropped a cylinder on the way home. Identical moulding and connector to the failed original I took out. Result is the rough idle and flashing engine light disappeared immediately.', 'Malik Novak', false, TRUE, '2025-12-31T18:51:50.792Z'),
  ('AUD-03N115562B', 2, 'Wrong housing diameter', 'Replacement for my 2016 A8 D4 3.0 TFSI V6. The gasket was dry and flat out of the packet and would not seat cleanly. Would not order the same one again.', 'Hugo Hoffmann', true, TRUE, '2025-10-30T15:38:12.727Z'),
  ('AUD-04E109119F', 4, 'Rattle on start-up gone', 'Second one of these I have bought, this time for the A4 B8. A weekend job with the right locking kit and a service manual open next to me. The date stamp was recent, which matters for rubber that has been sitting on a shelf. Result is the top-end rattle on cold start has completely gone. Cannot fault it.', 'Ines Moreau', false, TRUE, '2026-04-16T14:24:27.637Z'),
  ('AUD-04E109119F', 2, 'Chain stretched sooner than expected', 'Fitted to my 2011 A4 B8.5. It developed a light rattle again far sooner than a timing job should need redoing. Would not order the same one again.', 'Tobias Almeida', true, TRUE, '2025-03-10T07:25:49.676Z'),
  ('AUD-04E905110P', 5, 'No more limp mode', 'Second one of these I have bought, this time for the Q5 8R. A smear of dielectric grease went on the boot before it was seated. Identical moulding and connector to the failed original I took out. Result is fuel economy went back to normal within a tank. Will be back for the other side.', 'Chidi Whitfield', true, TRUE, '2026-06-15T22:05:58.239Z'),
  ('AUD-04E905110P', 5, 'Misfire cleared instantly', 'Second one of these I have bought, this time for the S4 B8. I replaced all four at once rather than chase them one at a time. Identical moulding and connector to the failed original I took out. Result is the rough idle and flashing engine light disappeared immediately. Would order again without hesitation.', 'Elena Almeida', true, TRUE, '2026-03-02T07:38:19.602Z'),
  ('AUD-04E905110P', 4, 'Straight fix for a rough idle', 'Cross-referenced the OE number against my 2021 S4 B8 before ordering. I replaced all four at once rather than chase them one at a time. The part number on the body matches the OE reference exactly. Result is fuel economy went back to normal within a tank. Delivery was quick too.', 'Nadia Vogel', true, TRUE, '2026-06-19T17:49:31.407Z'),
  ('AUD-057115561M', 3, 'Fine filter, seal was dry', 'Bought for a 2010 A7 4G. Two minutes behind the glovebox once I had the tabs released. The outer diameter was a couple of millimetres off and it would not sit square in the housing. That said, throttle response feels crisper than it did on the clogged original. Good part, minor niggles.', 'Greta Marchetti', true, TRUE, '2025-08-22T09:00:33.362Z'),
  ('AUD-058905261A', 3, 'Works fine, boots are stiff', 'Cross-referenced the OE number against my 2022 A3 8P before ordering. I cleared the fault codes afterwards and they have not come back. The part number on the body matches the OE reference exactly. That said, no stored codes after a month of daily driving. Worth buying, just go in with your eyes open.', 'Jonas Ellery', true, TRUE, '2025-07-15T21:32:29.984Z'),
  ('AUD-058905447C', 5, 'Straight fix for a rough idle', 'Went on my Q5 8R 1.8 TFSI at 94k miles. The spring contact is firm and seated with a definite click. Coil pack out, new one in, ten minutes with a T30 and the engine cover off. Result is it pulls cleanly through the rev range again with no stumble under load. Exactly what I needed.', 'Yara Ellery', true, TRUE, '2026-06-17T00:46:24.368Z'),
  ('AUD-058905447C', 5, 'Misfire cleared instantly', 'Ordered this for my Q8 4M after the original gave up at 61k. Coil pack out, new one in, ten minutes with a T30 and the engine cover off. Identical moulding and connector to the failed original I took out. Result is fuel economy went back to normal within a tank.', 'Yusuf Adeyemi', true, TRUE, '2025-04-22T15:02:04.751Z'),
  ('AUD-059109119F', 5, 'Peace of mind on an interference engine', 'My A3 8P needed this doing at 109k miles. The date stamp was recent, which matters for rubber that has been sitting on a shelf. A weekend job with the right locking kit and a service manual open next to me. Result is the top-end rattle on cold start has completely gone. No complaints at all.', 'Owen Rossi', true, TRUE, '2025-05-16T10:05:07.126Z'),
  ('AUD-059109229AA', 5, 'Everything lined up', 'Replacement for my 2012 S3 8V 2.0 TFSI. The chain has proper hardened links rather than the soft pins on cheap copies. Locking tools on, marks aligned, and it timed up exactly where it should. Result is the top-end rattle on cold start has completely gone. Cannot fault it.', 'Niall Delgado', false, TRUE, '2026-05-20T20:10:25.592Z'),
  ('AUD-059109229AA', 5, 'Rattle on start-up gone', 'My Q8 4M needed this doing at 166k miles. The tooth profile and belt width are indistinguishable from the part that came off. A weekend job with the right locking kit and a service manual open next to me. Result is the top-end rattle on cold start has completely gone. Happy to recommend it.', 'Talia Whitfield', false, TRUE, '2025-06-20T07:00:46.129Z'),
  ('AUD-059109229AA', 4, 'Peace of mind on an interference engine', 'Bought for a 2010 A1 8X. The tooth profile and belt width are indistinguishable from the part that came off. Locking tools on, marks aligned, and it timed up exactly where it should. Result is timing has held perfectly through 12,000 miles since fitting.', 'Amara Bauer', false, TRUE, '2026-01-24T05:33:35.974Z'),
  ('AUD-059109229K', 5, 'Quiet engine again', 'Replacement for my 2011 A8 D4 3.0 TDI V6. A weekend job with the right locking kit and a service manual open next to me. The date stamp was recent, which matters for rubber that has been sitting on a shelf. Result is timing has held perfectly through 12,000 miles since fitting.', 'Ines Vance', true, TRUE, '2026-01-15T09:16:42.127Z'),
  ('AUD-059109229K', 5, 'Everything lined up', 'Ordered this for my A5 8T after the original gave up at 69k. The chain has proper hardened links rather than the soft pins on cheap copies. I booked it in with a specialist rather than risk an interference engine on the driveway. Result is the engine is noticeably quieter at idle than it has been for a year.', 'Callum Whitfield', false, TRUE, '2026-01-09T07:54:28.819Z'),
  ('AUD-059109229M', 5, 'Rattle on start-up gone', 'Replacement for my 2016 A4 B8 1.8 TFSI. I booked it in with a specialist rather than risk an interference engine on the driveway. Everything in the box matched the parts diagram with nothing missing. Result is timing has held perfectly through 12,000 miles since fitting. Delivery was quick too.', 'Lena Whitfield', true, TRUE, '2026-05-12T06:26:00.421Z'),
  ('AUD-059109229M', 5, 'Peace of mind on an interference engine', 'My A6 C6 needed this doing at 115k miles. A weekend job with the right locking kit and a service manual open next to me. The chain has proper hardened links rather than the soft pins on cheap copies. Result is no more chain slap on start-up, which was what prompted the job. Cannot fault it.', 'Diego Okonkwo', true, TRUE, '2025-09-27T17:16:38.610Z'),
  ('AUD-059109229M', 4, 'Complete and correct', 'Bought for a 2007 Q8 4M. A weekend job with the right locking kit and a service manual open next to me. The tooth profile and belt width are indistinguishable from the part that came off. Result is no more chain slap on start-up, which was what prompted the job. Happy to recommend it.', 'Chidi Halvorsen', true, TRUE, '2026-02-18T15:32:11.888Z'),
